module find_longest_sequence (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] a_in [0:7],\n    input [7:0] b_in [0:7],\n    input [3:0] num_intervals,\n    output reg done,\n    output reg [3:0] length,\n    output reg [7:0] out_a [0:7],\n    output reg [7:0] out_b [0:7]\n);\n\n    // State declarations\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] LOAD        = 4'd1;\n    localparam [3:0] SORT        = 4'd2;\n    localparam [3:0] DP_INIT     = 4'd3;\n    localparam [3:0] DP_CALC     = 4'd4;\n    localparam [3:0] FIND_BEST   = 4'd5;\n    localparam [3:0] RECONSTRUCT = 4'd6;\n    localparam [3:0] OUTPUT      = 4'd7;\n    localparam [3:0] DONE_STATE  = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [7:0] intervals_a [0:7];\n    reg [7:0] intervals_b [0:7];\n    reg [3:0] sorted_idx [0:7];\n    reg [3:0] dp [0:7];\n    reg [3:0] prev [0:7];\n    reg [3:0] best_end;\n    reg [3:0] i, j, k;\n    reg [3:0] cycle_count;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            length <= 4'd0;\n            best_end <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            k <= 4'd0;\n            cycle_count <= 4'd0;\n            \n            for (integer n = 0; n < 8; n = n + 1) begin\n                intervals_a[n] <= 8'd0;\n                intervals_b[n] <= 8'd0;\n                sorted_idx[n] <= 4'd0;\n                dp[n] <= 4'd0;\n                prev[n] <= 4'd0;\n                out_a[n] <= 8'd0;\n                out_b[n] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 4'd0;\n                    if (start) begin\n                        state <= LOAD;\n                        i <= 4'd0;\n                    end\n                end\n                \n                LOAD: begin\n                    if (i < num_intervals) begin\n                        intervals_a[i] <= a_in[i];\n                        intervals_b[i] <= b_in[i];\n                        sorted_idx[i] <= i;\n                        i <= i + 4'd1;\n                    end else begin\n                        state <= SORT;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                    end\n                end\n                \n                SORT: begin\n                    cycle_count <= cycle_count + 4'd1;\n                    if (i < num_intervals - 4'd1) begin\n                        if (j < num_intervals - i - 4'd1) begin\n                            // Compare current and next element\n                            if ((intervals_a[sorted_idx[j]] > intervals_a[sorted_idx[j+4'd1]]) || \n                                (intervals_a[sorted_idx[j]] == intervals_a[sorted_idx[j+4'd1]] && \n                                 intervals_b[sorted_idx[j]] < intervals_b[sorted_idx[j+4'd1]])) begin\n                                // Swap indices\n                                sorted_idx[j] <= sorted_idx[j+4'd1];\n                                sorted_idx[j+4'd1] <= sorted_idx[j];\n                            end\n                            j <= j + 4'd1;\n                        end else begin\n                            i <= i + 4'd1;\n                            j <= 4'd0;\n                        end\n                    end else if (cycle_count > 4'd100) begin\n                        state <= DP_INIT; // Fallback if sorting takes too long\n                        i <= 4'd0;\n                    end else begin\n                        state <= DP_INIT;\n                        i <= 4'd0;\n                    end\n                end\n                \n                DP_INIT: begin\n                    if (i < num_intervals) begin\n                        dp[i] <= 4'd1;\n                        prev[i] <= 4'd15; // Invalid index\n                        i <= i + 4'd1;\n                    end else begin\n                        state <= DP_CALC;\n                        i <= 4'd1; // Start from second element\n                        j <= 4'd0;\n                    end\n                end\n                \n                DP_CALC: begin\n                    if (i < num_intervals) begin\n                        if (j < i) begin\n                            // Check if interval j contains interval i\n                            if (intervals_a[sorted_idx[j]] <= intervals_a[sorted_idx[i]] && \n                                intervals_b[sorted_idx[j]] >= intervals_b[sorted_idx[i]]) begin\n                                if (dp[j] + 4'd1 > dp[i]) begin\n                                    dp[i] <= dp[j] + 4'd1;\n                                    prev[i] <= j;\n                                end\n                            end\n                            j <= j + 4'd1;\n                        end else begin\n                            i <= i + 4'd1;\n                            j <= 4'd0;\n                        end\n                    end else begin\n                        state <= FIND_BEST;\n                        i <= 4'd0;\n                        best_end <= 4'd0;\n                    end\n                end\n                \n                FIND_BEST: begin\n                    if (i < num_intervals) begin\n                        if (dp[i] > dp[best_end]) begin\n                            best_end <= i;\n                        end\n                        i <= i + 4'd1;\n                    end else begin\n                        state <= RECONSTRUCT;\n                        length <= dp[best_end];\n                        i <= best_end;\n                        k <= 4'd0;\n                    end\n                end\n                \n                RECONSTRUCT: begin\n                    if (k < 8 && prev[i] != 4'd15) begin\n                        out_a[k] <= intervals_a[sorted_idx[i]];\n                        out_b[k] <= intervals_b[sorted_idx[i]];\n                        k <= k + 4'd1;\n                        i <= prev[i];\n                    end else if (k < 8) begin\n                        // Last element in sequence\n                        out_a[k] <= intervals_a[sorted_idx[i]];\n                        out_b[k] <= intervals_b[sorted_idx[i]];\n                        k <= k + 4'd1;\n                        state <= OUTPUT;\n                    end else begin\n                        state <= OUTPUT;\n                    end\n                end\n                \n                OUTPUT: begin\n                    if (k < 8) begin\n                        out_a[k] <= 8'd0;\n                        out_b[k] <= 8'd0;\n                        k <= k + 4'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule